using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using OFFSTEP.Data;using OFFSTEP.Models;
namespace OFFSTEP.Controllers;
[Authorize(Roles="Admin")] public class AdminCategoriesController:Controller
{private readonly ApplicationDbContext _db;public AdminCategoriesController(ApplicationDbContext db)=>_db=db;public async Task<IActionResult> Index()=>View(await _db.Categories.Include(x=>x.Products).OrderBy(x=>x.Name).ToListAsync());public IActionResult Create()=>View(new Category());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Create(Category c){if(!ModelState.IsValid)return View(c);_db.Categories.Add(c);await _db.SaveChangesAsync();return RedirectToAction(nameof(Index));}public async Task<IActionResult>Edit(int id){var c=await _db.Categories.FindAsync(id);return c==null?NotFound():View(c);}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Edit(int id,Category model){var c=await _db.Categories.FindAsync(id);if(c==null||id!=model.Id)return NotFound();if(!ModelState.IsValid)return View(model);c.Name=model.Name;c.Description=model.Description;await _db.SaveChangesAsync();return RedirectToAction(nameof(Index));}public async Task<IActionResult>Delete(int id){var c=await _db.Categories.Include(x=>x.Products).FirstOrDefaultAsync(x=>x.Id==id);return c==null?NotFound():View(c);}[HttpPost,ActionName("Delete"),ValidateAntiForgeryToken]public async Task<IActionResult>DeleteConfirmed(int id){var c=await _db.Categories.Include(x=>x.Products).FirstOrDefaultAsync(x=>x.Id==id);if(c!=null&&c.Products.Count==0){_db.Categories.Remove(c);await _db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}}
